command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-20k-browse --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "5eb0fbb50c627a736e8e6ca2bb4d9793ebad33ea") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-20k-browse origin/work/large-folder-20k-browse
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
if ((git rev-parse HEAD).Trim() -ne "8979948f8b519c5b6cc1bd133586b2474b2690cf") { throw "candidate mismatch" }

cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }

cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

$env:FLY_M16_CONFIG = "Release"
python -X utf8 tests\winui\helper\test_process_isolation.py
if ($LASTEXITCODE -ne 0) { throw "helper process-isolation regression failed" }

python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 2300 --configuration Release --resident-window-evidence after
if ($LASTEXITCODE -ne 0) { throw "matched folder-tab visual acceptance failed" }

python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 20500 --configuration Release --browse-over-complete-model
if ($LASTEXITCODE -ne 0) { throw "browse-over-20k acceptance failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "LARGE_FOLDER_20K_BROWSE_ACCEPTANCE_PASS"
